import React, { useState, useEffect, useRef } from 'react';
import { Send, User, Mic, StopCircle, RefreshCw, LogOut, Lightbulb, MessageCircle, X, Sparkles, TrendingDown, AlertTriangle, ArrowRight, ArrowLeft } from 'lucide-react';
import { Persona, Message, BigFive } from '../types';
import { startRoleplaySession, getCoachHint, getTurnFeedback, generateSpeech, parseSimulationResponse } from '../services/geminiService';
import { Chat } from '@google/genai';
import { Button, Input, Drawer, Avatar, Tooltip, Badge, Spin, Card as AntdCard, Switch, Tag, message as antdMessage, Modal } from 'antd';
import { SoundOutlined, MutedOutlined } from '@ant-design/icons';

const { TextArea } = Input;
const Card = AntdCard as any;

interface Props {
  persona: Persona;
  onFinish: (messages: Message[]) => void;
  onBack: () => void;
}

const BIG_FIVE_LABELS: Record<keyof BigFive, string> = {
  openness: '开放性',
  conscientiousness: '尽责性',
  extraversion: '外向性',
  agreeableness: '宜人性',
  neuroticism: '神经质'
};

export const StepChat: React.FC<Props> = ({ persona, onFinish, onBack }) => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputText, setInputText] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [chatSession, setChatSession] = useState<Chat | null>(null);
  const [isListening, setIsListening] = useState(false);
  const [audioEnabled, setAudioEnabled] = useState(true);
  const [browserSupportsSpeech, setBrowserSupportsSpeech] = useState(false);
  const [showMobileStats, setShowMobileStats] = useState(false);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const recognitionRef = useRef<any>(null);
  const baseInputTextRef = useRef<string>('');
  const audioContextRef = useRef<AudioContext | null>(null);

  useEffect(() => {
    // Check speech support
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    setBrowserSupportsSpeech(!!SpeechRecognition);

    const session = startRoleplaySession(persona);
    setChatSession(session);

    setMessages([
      {
        id: 'init',
        role: 'system',
        text: `场景加载完成。${persona.name} 已进入会议室。目标：传达 C 绩效评级并达成改进计划。`,
        timestamp: new Date()
      }
    ]);

    audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();

    return () => {
       if (audioContextRef.current && audioContextRef.current.state !== 'closed') {
           audioContextRef.current.close();
       }
       if (recognitionRef.current) {
           recognitionRef.current.stop();
       }
    };
  }, [persona]);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]); 

  // Additional delayed scroll for keyboard adjustments
  useEffect(() => {
    const timer = setTimeout(() => {
        scrollToBottom();
    }, 100);
    return () => clearTimeout(timer);
  }, [messages.map(m => m.analysis || m.suggestion).join('')]); 


  const toggleListening = () => {
    if (isListening) {
      recognitionRef.current?.stop();
      setIsListening(false);
    } else {
      const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
      if (!SpeechRecognition) return;

      baseInputTextRef.current = inputText;

      const recognition = new SpeechRecognition();
      recognition.lang = 'zh-CN';
      recognition.continuous = true;
      recognition.interimResults = true;

      recognition.onstart = () => setIsListening(true);
      recognition.onend = () => setIsListening(false);

      recognition.onerror = (event: any) => {
        if (event.error === 'no-speech' || event.error === 'aborted') {
            setIsListening(false);
            return;
        }
        setIsListening(false);
        if (event.error === 'not-allowed') antdMessage.error("无法访问麦克风");
      };

      recognition.onresult = (event: any) => {
        let speechTranscript = '';
        for (let i = 0; i < event.results.length; ++i) {
           speechTranscript += event.results[i][0].transcript;
        }
        const prefix = baseInputTextRef.current + (baseInputTextRef.current && !baseInputTextRef.current.endsWith(' ') && speechTranscript ? ' ' : '');
        setInputText(prefix + speechTranscript);
      };

      recognitionRef.current = recognition;
      try {
        recognition.start();
      } catch (e) {
        setIsListening(false);
      }
    }
  };

  const playAudioResponse = async (text: string) => {
    if (!audioEnabled || !audioContextRef.current) return;
    try {
       const buffer = await generateSpeech(text, persona.voiceName || 'Kore');
       if (buffer) {
          const source = audioContextRef.current.createBufferSource();
          source.buffer = buffer;
          source.connect(audioContextRef.current.destination);
          source.start();
       }
    } catch (e) { console.error(e); }
  };

  const handleSendMessage = async () => {
    if (!inputText.trim() || !chatSession) return;

    if (isListening) {
        recognitionRef.current?.stop();
        setIsListening(false);
    }

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      text: inputText,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMsg]);
    setInputText('');
    setIsLoading(true);

    // Force scroll after user send
    setTimeout(scrollToBottom, 50);

    try {
      const response = await chatSession.sendMessage({ message: userMsg.text });
      const parsed = parseSimulationResponse(response.text);

      const modelMsg: Message = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        text: parsed.text,
        scores: parsed.scores,
        evaluation: parsed.evaluation,
        timestamp: new Date()
      };

      setMessages(prev => [...prev, modelMsg]);

      if (audioEnabled) playAudioResponse(parsed.text);
    } catch (error) {
      console.error(error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleGetSuggestion = async (msg: Message) => {
    if (msg.suggestion || msg.isAnalyzing) return; 
    setMessages(prev => prev.map(m => m.id === msg.id ? { ...m, isAnalyzing: true } : m));
    try {
      const idx = messages.findIndex(m => m.id === msg.id);
      const suggestion = await getCoachHint(messages.slice(0, idx + 1), persona);
      setMessages(prev => prev.map(m => m.id === msg.id ? { ...m, isAnalyzing: false, suggestion } : m));
    } catch (e) {
      setMessages(prev => prev.map(m => m.id === msg.id ? { ...m, isAnalyzing: false } : m));
    }
  };

  const handleGetFeedback = async (msg: Message) => {
    if (msg.analysis || msg.isAnalyzing) return;
    setMessages(prev => prev.map(m => m.id === msg.id ? { ...m, isAnalyzing: true } : m));
    try {
      const idx = messages.findIndex(m => m.id === msg.id);
      const analysis = await getTurnFeedback(messages.slice(0, idx + 1), persona);
      setMessages(prev => prev.map(m => m.id === msg.id ? { ...m, isAnalyzing: false, analysis } : m));
    } catch (e) {
      setMessages(prev => prev.map(m => m.id === msg.id ? { ...m, isAnalyzing: false } : m));
    }
  };

  const clearAnalysis = (msgId: string) => {
    setMessages(prev => prev.map(m => m.id === msgId ? { ...m, analysis: undefined, suggestion: undefined } : m));
  };

  // Handler for mobile input focus to scroll view
  const handleInputFocus = () => {
     setTimeout(() => {
        scrollToBottom();
     }, 300);
  };

  // Profile Content Component (Shared between Drawer and Sidebar)
  const ProfileContent = () => (
     <div className="space-y-6">
         {/* Identity */}
         <div className="text-center">
             <Avatar size={80} src={persona.avatarUrl} shape="square" className="rounded-2xl border-4 border-white shadow-md mb-3" />
             {persona.personaTag && (
                <div className="mt-2">
                    <Tag color={
                        persona.personaTag.includes('防御') ? 'orange' :
                        persona.personaTag.includes('争辩') ? 'red' :
                        'blue'
                    }>{persona.personaTag}</Tag>
                </div>
             )}
             <h3 className="text-xl font-bold mt-2">{persona.name}</h3>
             <p className="text-slate-500">{persona.jobTitle} · {persona.yearsOfExperience}年</p>
         </div>

         {/* Performance */}
         <Card size="small" title={<span className="text-xs text-slate-400 uppercase font-bold flex items-center gap-1"><TrendingDown className="w-3 h-3"/> 绩效趋势</span>}>
             <div className="flex items-center gap-2 justify-center">
                 <div className="text-center p-2 bg-slate-50 rounded">
                     <div className="text-xs text-slate-400">上次</div>
                     <div className="font-bold">{persona.lastPerformance}</div>
                 </div>
                 <ArrowRight className="text-slate-300" />
                 <div className="text-center p-2 bg-red-50 rounded border border-red-100">
                     <div className="text-xs text-red-400">本次</div>
                     <div className="font-bold text-red-600">{persona.thisPerformance}</div>
                 </div>
             </div>
         </Card>

         {/* Pain Points */}
         <Card size="small" className="bg-amber-50 border-amber-100">
             <div className="flex items-center gap-2 mb-2 text-amber-700 font-bold text-xs uppercase">
                 <AlertTriangle className="w-3.5 h-3.5" /> 核心痛点
             </div>
             <p className="text-sm text-slate-700">{persona.businessPainPoints}</p>
         </Card>

         {/* Big Five */}
         <div>
            <div className="text-xs font-bold text-slate-400 uppercase mb-2">大五人格</div>
            <div className="flex flex-wrap gap-2">
                {Object.entries(persona.bigFive).map(([key, value]) => (
                    <Tag key={key} color={value === 'High' ? 'blue' : 'default'}>
                        {BIG_FIVE_LABELS[key as keyof BigFive]}: {value === 'High' ? '高' : '低'}
                    </Tag>
                ))}
            </div>
         </div>
     </div>
  );

  return (
    <div className="flex h-full max-w-7xl mx-auto gap-6 p-0 md:p-6 animate-fadeIn">

      {/* Mobile Drawer */}
      <Drawer
        placement="bottom"
        onClose={() => setShowMobileStats(false)}
        open={showMobileStats}
        height="85vh"
        title="角色档案"
        styles={{ body: { padding: '24px' } }}
      >
        <ProfileContent />
      </Drawer>

      {/* Desktop Sidebar */}
      <div className="w-80 hidden lg:flex flex-col bg-white rounded-3xl shadow-lg border border-slate-100 overflow-hidden h-full">
         <div className="flex-1 overflow-y-auto p-6 scrollbar-hide">
             <ProfileContent />
         </div>
         <div className="p-5 border-t border-slate-100 bg-slate-50 flex-shrink-0 space-y-4">
             <div className="flex items-center justify-between">
                  <span className="flex items-center gap-2 text-sm font-medium">
                      {audioEnabled ? <SoundOutlined className="text-blue-500"/> : <MutedOutlined />}
                      语音播报
                  </span>
                  <Switch checked={audioEnabled} onChange={setAudioEnabled} />
             </div>
             <Button danger block icon={<LogOut className="w-4 h-4" />} onClick={() => onFinish(messages)}>
                结束并生成报告
             </Button>
         </div>
      </div>

      {/* Main Chat Area */}
      <div className="flex-1 flex flex-col bg-white md:rounded-3xl shadow-none md:shadow-2xl shadow-slate-200/50 border-x-0 md:border md:border-slate-100 overflow-hidden relative h-full">
        {/* Chat Header */}
        <div className="bg-white/90 backdrop-blur-md border-b border-slate-100 p-3 md:p-4 flex justify-between items-center absolute top-0 left-0 right-0 z-10 shadow-sm">
           <div className="flex items-center gap-2 md:gap-3">
               <Tooltip title="退出并返回">
                   <Button 
                      type="text" 
                      icon={<ArrowLeft className="w-5 h-5 text-slate-600" />} 
                      onClick={() => {
                        Modal.confirm({
                          title: '退出演练',
                          content: '确定要返回角色选择吗？当前对话进度将丢失。',
                          okText: '确定离开',
                          cancelText: '继续演练',
                          okType: 'danger',
                          onOk: onBack,
                          centered: true,
                        });
                      }}
                   />
               </Tooltip>
               <div className="flex items-center gap-3 cursor-pointer" onClick={() => setShowMobileStats(true)}>
                   <div className="lg:hidden relative">
                      <Avatar src={persona.avatarUrl} />
                      <Badge status="processing" className="absolute bottom-0 right-0" />
                   </div>
                   <div>
                      <h2 className="font-bold text-slate-800 flex items-center gap-2 text-sm md:text-base">
                        绩效沟通会议
                        {isListening && <Tag color="red" className="animate-pulse m-0 border-0">正在录音...</Tag>}
                      </h2>
                   </div>
               </div>
           </div>
           <div className="lg:hidden">
              <Button danger size="small" onClick={() => onFinish(messages)}>结束</Button>
           </div>
        </div>

        {/* Chat Stream */}
        <div className="flex-1 overflow-y-auto p-3 md:p-6 pt-20 pb-4 bg-slate-50 space-y-6 scroll-smooth">
          {messages.map((msg) => (
            <div key={msg.id} className="space-y-2">
                <div className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                {msg.role === 'system' ? (
                    <div className="w-full flex justify-center my-6">
                        <Tag icon={<RefreshCw className="w-3 h-3 animate-spin mr-1"/>} className="rounded-full px-3 py-1 bg-slate-200 border-0 text-slate-600">
                            {msg.text}
                        </Tag>
                    </div>
                ) : (
                    <div className={`flex gap-3 max-w-[95%] md:max-w-[85%] ${msg.role === 'user' ? 'flex-row-reverse' : ''}`}>
                    <Avatar 
                        src={msg.role === 'model' ? persona.avatarUrl : undefined} 
                        icon={msg.role === 'user' && <User className="w-4 h-4" />} 
                        className={msg.role === 'user' ? 'bg-slate-900' : ''}
                        size={40}
                    />

                    <div className={`flex flex-col gap-2 min-w-[150px] md:min-w-[200px] ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                        {msg.role === 'model' && msg.evaluation && (
                            <div className="mb-1">
                                <Tag color={msg.evaluation.includes('负面') ? 'red' : msg.evaluation.includes('正面') ? 'green' : 'default'}>
                                    {msg.evaluation.includes('负面') ? '⚠️' : msg.evaluation.includes('正面') ? '✨' : '👀'} 评价: {msg.evaluation}
                                </Tag>
                            </div>
                        )}

                        <Card 
                            size="small"
                            className={`shadow-sm border-0 ${
                                msg.role === 'user' 
                                ? 'bg-blue-600 text-white rounded-tr-none' 
                                : 'bg-white text-slate-800 rounded-tl-none'
                            }`}
                            bodyStyle={{ padding: '12px 16px' }}
                        >
                            <span className="text-sm md:text-base whitespace-pre-wrap">{msg.text}</span>
                        </Card>

                        {/* Action Buttons */}
                        {msg.role === 'user' && (
                           <div className="flex gap-2 justify-end">
                              <Tooltip title="获取 AI 优化建议">
                                <Button 
                                    size="small" 
                                    type="text" 
                                    icon={msg.isAnalyzing && !msg.suggestion && !msg.analysis ? <Spin size="small"/> : <Lightbulb className="w-3.5 h-3.5" />}
                                    onClick={() => handleGetSuggestion(msg)}
                                    disabled={msg.isAnalyzing}
                                    className={msg.suggestion ? 'text-indigo-600 bg-indigo-50' : 'text-slate-500'}
                                >
                                    建议
                                </Button>
                              </Tooltip>

                              <Tooltip title="分析这句话的心理影响">
                                <Button 
                                    size="small" 
                                    type="text" 
                                    icon={msg.isAnalyzing && !msg.suggestion && !msg.analysis ? <Spin size="small"/> : <MessageCircle className="w-3.5 h-3.5" />}
                                    onClick={() => handleGetFeedback(msg)}
                                    disabled={msg.isAnalyzing}
                                    className={msg.analysis ? 'text-amber-600 bg-amber-50' : 'text-slate-500'}
                                >
                                    分析
                                </Button>
                              </Tooltip>
                           </div>
                        )}
                    </div>
                    </div>
                )}
                </div>

                {(msg.analysis || msg.suggestion) && (
                    <div className={`flex w-full animate-slideUp ${msg.role === 'user' ? 'justify-end' : 'justify-start ml-12 md:ml-14'}`}>
                        <div className={`bg-slate-800 text-slate-200 rounded-2xl p-4 shadow-xl text-sm relative border border-slate-700 max-w-[90%] md:max-w-[85%] ${msg.role === 'user' ? 'mr-12 md:mr-14' : ''}`}>
                             <Button 
                                type="text" 
                                icon={<X className="w-4 h-4 text-slate-400" />} 
                                onClick={() => clearAnalysis(msg.id)}
                                className="absolute top-1 right-1 hover:bg-slate-700"
                             />

                             {msg.suggestion && (
                                <div className="mb-4 last:mb-0">
                                    <h5 className="flex items-center gap-2 text-indigo-400 font-bold text-xs uppercase tracking-wider mb-2">
                                        <Sparkles className="w-4 h-4" /> 建议优化方向
                                    </h5>
                                    <div className="space-y-1 text-slate-300 whitespace-pre-line pl-2 border-l-2 border-indigo-500/30">
                                        {msg.suggestion}
                                    </div>
                                </div>
                             )}

                             {msg.analysis && (
                                <div className="last:mb-0">
                                    <h5 className="flex items-center gap-2 text-amber-400 font-bold text-xs uppercase tracking-wider mb-2">
                                        <MessageCircle className="w-4 h-4" /> 话术分析
                                    </h5>
                                    <div className="space-y-1 text-slate-300 whitespace-pre-line pl-2 border-l-2 border-amber-500/30">
                                        {msg.analysis}
                                    </div>
                                </div>
                             )}
                        </div>
                    </div>
                )}
            </div>
          ))}

          {isLoading && (
            <div className="flex justify-start pl-2">
                 <div className="bg-white p-4 rounded-2xl rounded-tl-none border border-slate-100 shadow-sm">
                     <Spin tip="对方正在思考..." size="small" />
                 </div>
            </div>
          )}
          <div ref={messagesEndRef} />
        </div>

        {/* Input Area */}
        <div className="p-3 md:p-6 bg-white border-t border-slate-100 z-20 flex-shrink-0">
          <div className="flex gap-2 items-end">
            <div className="flex-1 relative">
                <TextArea
                    value={inputText}
                    disabled={isLoading || isListening}
                    onFocus={handleInputFocus}
                    onChange={(e) => setInputText(e.target.value)}
                    onKeyDown={(e) => {
                        if (e.key === 'Enter' && !e.shiftKey) {
                            e.preventDefault();
                            handleSendMessage();
                        }
                    }}
                    placeholder={isListening ? "正在聆听..." : "输入你的回复..."}
                    autoSize={{ minRows: 1, maxRows: 4 }}
                    className="text-base py-3 pr-10"
                    style={{ fontSize: '16px' }}
                />

                <Tooltip title={isListening ? "停止录音" : "语音输入"}>
                    <Button 
                        type="text"
                        shape="circle"
                        icon={isListening ? <StopCircle className="w-5 h-5 text-red-500 animate-pulse" /> : <Mic className="w-5 h-5 text-slate-400" />}
                        onClick={toggleListening}
                        disabled={!browserSupportsSpeech}
                        className="absolute right-1 bottom-1"
                    />
                </Tooltip>
            </div>

            <Button 
                type="primary" 
                shape="circle" 
                size="large"
                icon={<Send className="w-5 h-5" />}
                onClick={handleSendMessage}
                disabled={isLoading || !inputText.trim() || isListening}
                className="flex-shrink-0 mb-0.5"
            />
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { Activity, Sparkles, Target, Quote } from 'lucide-react';
import { Message, Persona, FeedbackReport } from '../types';
import { generateSessionReport } from '../services/geminiService';
import { saveSession, updateSession } from '../services/storage';
import { Radar, RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, ResponsiveContainer } from 'recharts';
import { Button, Card as AntdCard, Rate, Tag, Progress, Row, Col, Typography, Spin, Result as AntdResult } from 'antd';
import { ReloadOutlined } from '@ant-design/icons';

const { Title, Paragraph, Text } = Typography;
const Card = AntdCard as any;
const Result = AntdResult as any;

interface Props {
  messages: Message[];
  persona: Persona;
  onRestart: () => void;
  existingReport?: FeedbackReport; 
  existingNps?: number;
}

const getGrade = (score: number) => {
  if (score >= 90) return { label: 'S', color: '#ca8a04', text: '完美应对' };
  if (score >= 80) return { label: 'A', color: '#16a34a', text: '非常优秀' };
  if (score >= 70) return { label: 'B', color: '#2563eb', text: '合格通过' };
  if (score >= 60) return { label: 'C', color: '#ea580c', text: '有待提升' };
  return { label: 'D', color: '#dc2626', text: '演练失败' };
};

export const StepReport: React.FC<Props> = ({ messages, persona, onRestart, existingReport, existingNps }) => {
  const [report, setReport] = useState<FeedbackReport | null>(existingReport || null);
  const [loading, setLoading] = useState(!existingReport);
  const [sessionId, setSessionId] = useState<string>('');
  const [npsScore, setNpsScore] = useState<number | null>(existingNps !== undefined ? existingNps : null);
  const [npsSubmitted, setNpsSubmitted] = useState(existingNps !== undefined);

  useEffect(() => {
    if (existingReport) return;

    const fetchReport = async () => {
      const conversationHistory = messages.filter(m => m.role !== 'system');
      const data = await generateSessionReport(conversationHistory, persona);

      const newId = Date.now().toString();
      saveSession({
        id: newId,
        date: new Date().toISOString(),
        persona: persona,
        messages: messages,
        report: data
      });
      setSessionId(newId);

      setReport(data);
      setLoading(false);
    };
    fetchReport();
  }, [messages, persona, existingReport]);

  const handleSubmitNPS = (score: number) => {
    setNpsScore(score);
    if (sessionId) {
      updateSession(sessionId, { nps: score });
    }
    setNpsSubmitted(true);
  };

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center h-full bg-slate-50">
         <Spin size="large" tip="AI 教练正在复盘分析中..." />
         <div className="mt-4 text-slate-500 text-sm">正在评估同理心、沟通清晰度与目标达成率</div>
      </div>
    );
  }

  if (!report) return null;

  const grade = getGrade(report.score);

  const radarData = [
    { subject: '同理心', A: report.empathyScore, fullMark: 100 },
    { subject: '清晰度', A: report.clarityScore, fullMark: 100 },
    { subject: '目标达成', A: report.goalAchievementScore, fullMark: 100 },
  ];

  return (
    <div className="h-full overflow-y-auto bg-slate-50 animate-fadeIn scrollbar-hide pb-safe-bottom">
      <div className="max-w-5xl mx-auto">

        {/* Header Section */}
        <div className="bg-white border-b border-slate-200 p-4 md:p-8">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                <div>
                   <div className="flex items-center gap-2 mb-2">
                       <Tag>{persona.jobTitle}</Tag>
                       <span className="text-slate-500 text-sm">{new Date().toLocaleDateString()}</span>
                   </div>
                   <Title level={2} style={{ margin: 0 }} className="text-xl md:text-3xl">演练评估报告</Title>
                   <Text type="secondary" className="text-xs md:text-sm">智能分析完成</Text>
                </div>
                <Button type="primary" size="large" icon={<ReloadOutlined />} onClick={onRestart} className="w-full md:w-auto">
                   再次演练
                </Button>
            </div>
        </div>

        <div className="p-4 md:p-8 space-y-6">

            {/* 1. Score Dashboard */}
            <Row gutter={[24, 24]}>
                 <Col xs={24} md={9}>
                     <div className="h-full bg-white rounded-2xl shadow-sm border border-slate-200 p-8 flex flex-col items-center justify-center text-center relative overflow-hidden">
                         <div className="absolute top-0 right-0 w-24 h-24 bg-gradient-to-bl from-slate-100 to-transparent rounded-bl-[100px] pointer-events-none"></div>

                         <div className="text-slate-400 text-sm font-medium mb-4 uppercase tracking-wider">综合得分</div>

                         <div className="flex items-baseline justify-center mb-6">
                            <span className="text-6xl md:text-7xl font-bold transition-all duration-500" style={{ color: grade.color }}>
                                {report.score}
                            </span>
                            <span className="text-2xl text-slate-300 font-medium ml-2">/ 100</span>
                         </div>

                         <div 
                            className="px-8 py-2 rounded-lg text-white font-bold text-lg shadow-md transform hover:scale-105 transition-transform"
                            style={{ backgroundColor: grade.color }}
                         >
                            {grade.label} - {grade.text}
                         </div>
                     </div>
                 </Col>

                 <Col xs={24} md={15}>
                     <div className="h-full bg-white rounded-2xl shadow-sm border border-slate-200 p-6 md:p-8">
                        <Row align="middle" className="h-full" gutter={[0, 24]}>
                            <Col xs={24} sm={14} className="h-64">
                                <ResponsiveContainer width="100%" height="100%">
                                    <RadarChart cx="50%" cy="50%" outerRadius="70%" data={radarData}>
                                        <PolarGrid stroke="#e2e8f0" />
                                        <PolarAngleAxis dataKey="subject" tick={{ fontSize: 12, fill: '#64748b' }} />
                                        <PolarRadiusAxis angle={30} domain={[0, 100]} tick={false} axisLine={false} />
                                        <Radar 
                                            name="Performance" 
                                            dataKey="A" 
                                            stroke="#94a3b8" 
                                            strokeWidth={2}
                                            fill="#cbd5e1" 
                                            fillOpacity={0.4} 
                                        />
                                    </RadarChart>
                                </ResponsiveContainer>
                            </Col>
                            <Col xs={24} sm={10}>
                                <div className="space-y-6 pl-0 md:pl-4">
                                    <h4 className="font-bold flex items-center gap-2 text-slate-700">
                                        <Activity className="w-4 h-4 text-blue-500" /> 
                                        维度拆解
                                    </h4>
                                    <div className="space-y-4">
                                        <div>
                                            <div className="flex justify-between text-xs mb-1 text-slate-500 font-medium">
                                                <span>同理心</span>
                                                <span>{report.empathyScore}</span>
                                            </div>
                                            <Progress percent={report.empathyScore} showInfo={false} strokeColor="#94a3b8" trailColor="#f1f5f9" size="small" />
                                        </div>
                                        <div>
                                            <div className="flex justify-between text-xs mb-1 text-slate-500 font-medium">
                                                <span>清晰度</span>
                                                <span>{report.clarityScore}</span>
                                            </div>
                                            <Progress percent={report.clarityScore} showInfo={false} strokeColor="#94a3b8" trailColor="#f1f5f9" size="small" />
                                        </div>
                                        <div>
                                            <div className="flex justify-between text-xs mb-1 text-slate-500 font-medium">
                                                <span>目标达成</span>
                                                <span>{report.goalAchievementScore}</span>
                                            </div>
                                            <Progress percent={report.goalAchievementScore} showInfo={false} strokeColor="#94a3b8" trailColor="#f1f5f9" size="small" />
                                        </div>
                                    </div>
                                </div>
                            </Col>
                        </Row>
                     </div>
                 </Col>
            </Row>

            {/* 2. Executive Summary */}
            <Card className="bg-slate-900 border-none shadow-lg rounded-2xl" bodyStyle={{ padding: '24px 32px' }}>
                <div className="relative z-10">
                   <div className="flex items-center gap-2 mb-3">
                       <span className="w-1 h-4 bg-blue-500 rounded-full"></span>
                       <Text className="text-slate-400 text-xs font-bold tracking-wider uppercase">AI 教练点评</Text>
                   </div>
                   <Paragraph className="text-white text-base md:text-lg font-medium mb-0 leading-relaxed indent-0 opacity-95">
                       <Quote className="w-8 h-8 text-slate-700 inline mr-2 align-top transform -scale-x-100" />
                       {report.summary}
                   </Paragraph>
                </div>
            </Card>

            {/* 3. Feedback Grid */}
            <Row gutter={[24, 24]}>
                 <Col xs={24} md={12}>
                     <div className="h-full bg-green-50/50 border border-green-100 rounded-2xl p-6">
                        <div className="flex items-center gap-2 mb-4">
                            <Sparkles className="w-5 h-5 text-green-600"/> 
                            <span className="font-bold text-green-900">亮点表现</span>
                        </div>
                        <ul className="space-y-4 pl-0 list-none mb-0">
                           {report.strengths.map((point, i) => (
                              <li key={i} className="flex items-start gap-3">
                                 <div className="w-6 h-6 rounded-full bg-green-200 text-green-700 flex items-center justify-center flex-shrink-0 text-xs font-bold shadow-sm">{i+1}</div>
                                 <span className="text-green-900 text-sm leading-6 pt-0.5">{point}</span>
                              </li>
                           ))}
                        </ul>
                     </div>
                 </Col>

                 <Col xs={24} md={12}>
                     <div className="h-full bg-orange-50/50 border border-orange-100 rounded-2xl p-6">
                        <div className="flex items-center gap-2 mb-4">
                            <Target className="w-5 h-5 text-orange-600"/> 
                            <span className="font-bold text-orange-900">提升建议</span>
                        </div>
                        <ul className="space-y-4 pl-0 list-none mb-0">
                           {report.improvements.map((point, i) => (
                              <li key={i} className="flex items-start gap-3">
                                 <div className="w-6 h-6 rounded-full bg-orange-200 text-orange-700 flex items-center justify-center flex-shrink-0 text-xs font-bold shadow-sm">{i+1}</div>
                                 <span className="text-orange-900 text-sm leading-6 pt-0.5">{point}</span>
                              </li>
                           ))}
                        </ul>
                     </div>
                 </Col>
            </Row>

            {/* 4. NPS */}
            <div className="bg-white rounded-2xl border border-slate-100 p-8 text-center mt-8">
                {!npsSubmitted ? (
                    <>
                        <Title level={4} className="text-base md:text-lg mb-6">本次模拟对您有帮助吗？</Title>
                        <div className="flex justify-center">
                            <Rate 
                                count={10} 
                                onChange={handleSubmitNPS} 
                                className="text-2xl md:text-3xl [&_.ant-rate-star-second]:text-slate-200 [&_.ant-rate-star-full_.ant-rate-star-second]:text-yellow-400" 
                            />
                        </div>
                    </>
                ) : (
                    <Result
                        status="success"
                        title="感谢您的反馈！"
