       - 什么是带教 (GROW): https://ihub.ctripcorp.com/front/course/detail/7724?itemid=15637
  `;

  const schema: Schema = {
    type: Type.OBJECT,
    properties: {
      score: { type: Type.NUMBER },
      level: { type: Type.STRING, enum: ["新手级", "发展中", "胜任级", "卓越级"] },
